(6999156, 1057278, 47597, '<td valign="top">Lovely tones. I like the vignette effect.</td>', 'Lovely tones. I like the vignette effect.', '2013-03-13 15:57:05.000000', NULL, 1),
(6999157, 1057978, 109227, '<td valign="top">I really like this image, it has nice light and the coloring looks natural.  IMO, a little shadow on the left side of the face (non light side) would give it more dimension.  Also, I think the cup is not needed. I am not an expert, so take this with a grain of salt; overall, a nice image.</td>', 'I really like this image, it has nice light and the coloring looks natural.  IMO, a little shadow on the left side of the face (non light side) would give it more dimension.  Also, I think the cup is not needed. I am not an expert, so take this with a grain of salt; overall, a nice image.', '2013-03-13 15:57:44.000000', NULL, 1),
(6999158, 1057857, 109227, '<td valign="top">This is the most intriguing image in the challenge (IMO).  I like all the dimensions, the detail and the tones.</td>', 'This is the most intriguing image in the challenge (IMO).  I like all the dimensions, the detail and the tones.', '2013-03-13 15:58:30.000000', NULL, 1),
