(6999163, 1057182, 109227, '<td valign="top">Love the little smirky bout.  Nice use of light.</td>', 'Love the little smirky bout.  Nice use of light.', '2013-03-13 16:00:07.000000', NULL, 1),
(6999164, 1057542, 109227, '<td valign="top">This is a beautiful high key image; IMO, it would do just as well without the camera.</td>', 'This is a beautiful high key image; IMO, it would do just as well without the camera.', '2013-03-13 16:00:30.000000', NULL, 1),
(6999166, 1057047, 109227, '<td valign="top">Great light and love the expression.</td>', 'Great light and love the expression.', '2013-03-13 16:00:41.000000', NULL, 1),
(6999168, 1058018, 109227, '<td valign="top">Great light, detail and color.  I think it would do just as well without the eyes covered, as it is beautiful contrast with the hair and the red accents.</td>', 'Great light, detail and color.  I think it would do just as well without the eyes covered, as it is beautiful contrast with the hair and the red accents.', '2013-03-13 16:01:35.000000', NULL, 1),
