(6999183, 1058070, 109227, '<td valign="top">Nice portrait of "the bear".  I like the softness and the little smile.</td>', 'Nice portrait of "the bear".  I like the softness and the little smile.', '2013-03-13 16:07:32.000000', NULL, 1),
(6999184, 1058188, 47597, '<td valign="top">The bum is too prominent. I think a crop that just showed her bare back and shoulder with the same expression on her face would do better.</td>', 'The bum is too prominent. I think a crop that just showed her bare back and shoulder with the same expression on her face would do better.', '2013-03-13 16:08:18.000000', NULL, 1),
(6999185, 1058234, 109227, '<td valign="top">This is a good portrait; I would like to see it with less negative space, I think that might bring her forward and we could see her over the background.  Still, nice light and detail.</td>', 'This is a good portrait; I would like to see it with less negative space, I think that might bring her forward and we could see her over the background.  Still, nice light and detail.', '2013-03-13 16:08:47.000000', NULL, 1),
(6999186, 1058064, 109227, '<td valign="top">A sweet face.  I think it may be a little too soft, especially in the eyes, but still a nice image.</td>', 'A sweet face.  I think it may be a little too soft, especially in the eyes, but still a nice image.', '2013-03-13 16:09:33.000000', NULL, 1),
(6999187, 1057956, 109227, '<td valign="top">Nice high key and a beautiful child.  The eyes and face look a little soft, but that could be from the high key lighting.  Nice expression too.</td>', 'Nice high key and a beautiful child.  The eyes and face look a little soft, but that could be from the high key lighting.  Nice expression too.', '2013-03-13 16:10:24.000000', NULL, 1),
(6999190, 1058188, 109227, '<td valign="top">Lighting is nice and she is a beautiful model; however, I am drawn to her backside rather than the beautiful face which is less prominent.</td>', 'Lighting is nice and she is a beautiful model; however, I am drawn to her backside rather than the beautiful face which is less prominent.', '2013-03-13 16:11:37.000000', NULL, 1),
(6999193, 1057836, 109227, '<td valign="top">Nice crop and perspective for this one.  I think it is a little too soft, but I am no expert, so take that with a grain of salt.  Cute baby.</td>', 'Nice crop and perspective for this one.  I think it is a little too soft, but I am no expert, so take that with a grain of salt.  Cute baby.', '2013-03-13 16:12:49.000000', NULL, 1),
(6999194, 1057479, 109227, '<td valign="top">I really don''t like snakes and I can''t get past the snake head to see the beautiful model, lol.  Nice lighting.</td>', 'I really don''t like snakes and I can''t get past the snake head to see the beautiful model, lol.  Nice lighting.', '2013-03-13 16:13:43.000000', NULL, 1),
(6999196, 1058042, 109227, '<td valign="top">Great lighting, detail and tones.</td>', 'Great lighting, detail and tones.', '2013-03-13 16:14:03.000000', NULL, 1),
