(6999233, 1058188, 26464, '<td valign="top">nice skin textures.</td>', 'nice skin textures.', '2013-03-13 17:13:40.000000', NULL, 1),
(6999243, 1057874, 53147, '<td valign="top">This is my kind of portrait. Especially at this age. There is an interesting look into who he will be and who he once was. You can see the kid but also the adult. And I also like seeing our kids grow up in the challenges. Lovely image. If this were mine this would be on a canvas hanging on my wall before the challenge was over.</td>', 'This is my kind of portrait. Especially at this age. There is an interesting look into who he will be and who he once was. You can see the kid but also the adult. And I also like seeing our kids grow up in the challenges. Lovely image. If this were mine this would be on a canvas hanging on my wall before the challenge was over.', '2013-03-13 17:24:30.000000', NULL, 1),
(6999246, 1057276, 108580, '<td valign="top">Sorry but I actually thought Mickey Mouse...Nice light paint technique though!</td>', 'Sorry but I actually thought Mickey Mouse...Nice light paint technique though!', '2013-03-13 17:27:43.000000', NULL, 1),
(6999251, 1058066, 159525, '<td valign="top">I love his smile, it feels genuine.!</td>', 'I love his smile, it feels genuine.!', '2013-03-13 17:34:39.000000', NULL, 1),
