INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6999391, 1058235, 159525, '<td valign="top">You should have entered this in the minimal portrait challenge.  I don''t think you took advantage of advanced editing.   I still enjoy the humor.</td>', 'You should have entered this in the minimal portrait challenge.  I don''t think you took advantage of advanced editing.   I still enjoy the humor.', '2013-03-13 19:50:59.000000', NULL, 1),
(6999392, 1057851, 159525, '<td valign="top">I hope nothing is wrong with her eyes, but for some reason I feel disturbed by them.</td>', 'I hope nothing is wrong with her eyes, but for some reason I feel disturbed by them.', '2013-03-13 19:52:35.000000', NULL, 1),
(6999394, 1058208, 159525, '<td valign="top">I really like the emotion of the subject...I don''t like the shadow!</td>', 'I really like the emotion of the subject...I don''t like the shadow!', '2013-03-13 19:53:09.000000', NULL, 1),
(6999395, 1058018, 159525, '<td valign="top">The flower petal and baby breath in her hair I love, but the flowers on the eyes ruin for me.  I''m still gong to give you a good score because I like that you put thought into this.</td>', 'The flower petal and baby breath in her hair I love, but the flowers on the eyes ruin for me.  I''m still gong to give you a good score because I like that you put thought into this.', '2013-03-13 19:56:30.000000', NULL, 1),
(6999403, 1058039, 159525, '<td valign="top">This is very successful if you were going for the crime look!</td>', 'This is very successful if you were going for the crime look!', '2013-03-13 20:03:37.000000', NULL, 1),
(6999446, 1058242, 109227, '<td valign="top">Here''s that cute as pie baby again.  Nicely lit and processed.</td>', 'Here''s that cute as pie baby again.  Nicely lit and processed.', '2013-03-13 21:24:04.000000', NULL, 1),
(6999447, 1057983, 109227, '<td valign="top">I really like this image for it''s real life approach.</td>', 'I really like this image for it''s real life approach.', '2013-03-13 21:24:20.000000', NULL, 1),
(6999449, 1057182, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>This is absolutely TOP NOTCH! The lighting and the capture of expression there is something that is both captivating and akin to a painting...I think of the expression and light from Vermeer''s Girl with Pearl Earring. Excellent work - 10.</td>', 'Voted earlier coming back to comment. This is absolutely TOP NOTCH! The lighting and the capture of expression there is something that is both captivating and akin to a painting...I think of the expression and light from Vermeer''s Girl with Pearl Earring. Excellent work - 10.', '2013-03-13 21:26:51.000000', NULL, 1),
(6999450, 1057894, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Love the mood, the lighting and the feeling behind this portrait. Even though only half the face is visible it speaks to me that music it a vital part of this person''s life. Well done.</td>', 'Voted earlier coming back to comment. Love the mood, the lighting and the feeling behind this portrait. Even though only half the face is visible it speaks to me that music it a vital part of this person''s life. Well done.', '2013-03-13 21:28:51.000000', NULL, 1),
(6999451, 1057122, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>The lack of strong contrasts and color <u>do not detract</u> from this photograph but enhances it. Why? Because I get the strong sense of an old photograph. The mood and feel is of time gone by. The beauty of this person is forever captured/frozen in time to appreciate. The ladies features and the crown of flowers makes me think of Hawaii'' sometime in the 1940''s. Very nicely presented and done.</td>', 'Voted earlier coming back to comment. The lack of strong contrasts and color do not detract from this photograph but enhances it. Why? Because I get the strong sense of an old photograph. The mood and feel is of time gone by. The beauty of this person is forever captured/frozen in time to appreciate. The ladies features and the crown of flowers makes me think of Hawaii'' sometime in the 1940''s. Very nicely presented and done.', '2013-03-13 21:32:55.000000', NULL, 1),
(6999457, 1058070, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Great light, great details, great friendly smile and absolutely great title that is a nod capturing the spirit of the person. Top tier work. The only thing I wish that this photo better captured is a little twinkle or catchlight in his eyes to further complement the character of the man who is Bear_Music.</td>', 'Voted earlier coming back to comment. Great light, great details, great friendly smile and absolutely great title that is a nod capturing the spirit of the person. Top tier work. The only thing I wish that this photo better captured is a little twinkle or catchlight in his eyes to further complement the character of the man who is Bear_Music.', '2013-03-13 21:41:21.000000', NULL, 1),
