(7000356, 1057479, 140305, '<td valign="top">Voted earlier, commenting only<br/> <br/>No one can accuse this of not being original, creative, beautifully lit, something to stop and really take a look at. Great jobb!</td>', 'Voted earlier, commenting only No one can accuse this of not being original, creative, beautifully lit, something to stop and really take a look at. Great jobb!', '2013-03-14 23:57:56.000000', NULL, 1),
(7000582, 1057731, 47597, '<td valign="top">I think this is one of those portraits that would be wonderful if we could see something of her environment, rather than a black background. Especially given your title. Or maybe a prop?</td>', 'I think this is one of those portraits that would be wonderful if we could see something of her environment, rather than a black background. Especially given your title. Or maybe a prop?', '2013-03-15 07:19:15.000000', NULL, 1),
