(7001019, 1058245, 124982, '<td valign="top">Very powerful and moody image. The dark, low-key image seems to fit the expression very nicely.</td>', 'Very powerful and moody image. The dark, low-key image seems to fit the expression very nicely.', '2013-03-15 18:13:49.000000', NULL, 1),
(7001020, 1058042, 124982, '<td valign="top">Great lighting and B&amp;W processing. Only thing that detracts are the heavy shadows in the corners of the eye. For some reason they seem to pull my eye to them.</td>', 'Great lighting and B&W processing. Only thing that detracts are the heavy shadows in the corners of the eye. For some reason they seem to pull my eye to them.', '2013-03-15 18:14:56.000000', NULL, 1),
