(7001026, 1058261, 124982, '<td valign="top">Bizarre, Jeff!! Once again the lighting and processing are top notch. Looks like something out of A Clockwork Orange!</td>', 'Bizarre, Jeff!! Once again the lighting and processing are top notch. Looks like something out of A Clockwork Orange!', '2013-03-15 18:19:00.000000', NULL, 1),
(7001027, 1057799, 124982, '<td valign="top">Lovely model and very powerful pose!! Just wish the lighting on her face was a little better. You have some lovely sunlight to play with, unfortunately her face is in the shade. Still, I really love this!</td>', 'Lovely model and very powerful pose!! Just wish the lighting on her face was a little better. You have some lovely sunlight to play with, unfortunately her face is in the shade. Still, I really love this!', '2013-03-15 18:20:31.000000', NULL, 1),
(7001028, 1058165, 124982, '<td valign="top">How macabre and lovely~! The lighting and composition are spot on! Quite bizarre...but very cool!</td>', 'How macabre and lovely~! The lighting and composition are spot on! Quite bizarre...but very cool!', '2013-03-15 18:21:11.000000', NULL, 1),
(7001029, 1057182, 124982, '<td valign="top">I love everything about this image --- except maybe the "painterly" processing. I''m on the fence about whether it adds or detracts from it. Will come back later to vote after I''ve thought on it some more.</td>', 'I love everything about this image --- except maybe the "painterly" processing. I''m on the fence about whether it adds or detracts from it. Will come back later to vote after I''ve thought on it some more.', '2013-03-15 18:22:24.000000', NULL, 1),
(7001033, 1058257, 124982, '<td valign="top">Quite splendidly done. Gorgeous model and lighting. Touch overdone on skin processing around face....but I realize everyone''s tastes differ. Lovely!</td>', 'Quite splendidly done. Gorgeous model and lighting. Touch overdone on skin processing around face....but I realize everyone''s tastes differ. Lovely!', '2013-03-15 18:27:51.000000', NULL, 1),
(7001035, 1057968, 124982, '<td valign="top">Can I say just how much I appreciate this portrait? It''s natural, unembellished, simple -- but so real. And so appealing. Makes for a lovely change from the intricate studio compositions and over-processed images. Quite delightful.</td>', 'Can I say just how much I appreciate this portrait? It''s natural, unembellished, simple -- but so real. And so appealing. Makes for a lovely change from the intricate studio compositions and over-processed images. Quite delightful.', '2013-03-15 18:29:59.000000', NULL, 1),
(7001038, 1057479, 124982, '<td valign="top">Typical <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=96751" rel="nofollow" target="_blank">tanguera</a> image -- perfectly composed and lit. Very powerful, striking image. Model has some biceps too!! Wonderful portrait. Top 3 for sure.</td>', 'Typical  tanguera image -- perfectly composed and lit. Very powerful, striking image. Model has some biceps too!! Wonderful portrait. Top 3 for sure.', '2013-03-15 18:31:32.000000', NULL, 1),
(7001039, 1058070, 124982, '<td valign="top">What, a "normal" Robert image without the heavy processing. Quite a striking man when he''s not processed to look like a weathered old man!</td>', 'What, a "normal" Robert image without the heavy processing. Quite a striking man when he''s not processed to look like a weathered old man!', '2013-03-15 18:33:00.000000', NULL, 1),
